cards:[
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "1 ▶ What is REST? (The answer that is not “an API that returns JSON.”)",
  "a": "An architectural style — a set of constraints Roy Fielding identified as the reason the web scales (2000 PhD): client–server, statelessness, cacheability, uniform interface, layered system, code-on-demand. Most “REST APIs” drop hypermedia and keep the valuable resource model + HTTP semantics. (Part 1)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "2 ▶ Resource vs representation — and why is GET /getBook?id=42 an RPC costume?",
  "a": "The resource is the abstract thing (book, order, weather); what crosses the wire is a representation of it, chosen via Accept. URLs name THINGS, never actions — verbs already exist as HTTP methods. (Part 2)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "3 ▶ Safe vs idempotent — and why is a GET that deletes a genuine bug?",
  "a": "Safe = no server-state change (GET, HEAD). Idempotent = N identical requests have the same effect as one (GET, PUT, DELETE; NOT POST). A GET-that-deletes gets triggered eventually by a crawler or a link preview. (Part 2)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "4 ▶ PUT vs PATCH: omit a field in each. What have you said?",
  "a": "PUT: “this is the complete new state” — the field should be ABSENT, replace the resource. PATCH: “a description of changes” — omit and you said leave it alone. PUT replaces; PATCH modifies. (Part 2)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "5 ▶ 401 vs 403 — one sentence each.",
  "a": "401 Unauthorized: “I don’t know who you are” — you didn’t prove identity (the name is a historical misnomer). 403 Forbidden: “I know exactly who you are, and no” — authenticated but not permitted. Asked in almost every interview. (Part 2)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "6 ▶ Status families, and why 200-with-error is a broken API.",
  "a": "2xx worked, 3xx look elsewhere, 4xx YOU sent something wrong (retrying identically won’t help), 5xx THE SERVER failed (retry may work). The code is for machines — a 200 body with {\"error\": \"not found\"} fools every client, cache, and monitor. (Parts 2, 5)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "7 ▶ The URL design rules in one breath.",
  "a": "URLs are nouns, methods are verbs (/books, DELETE /books/42); plural collections, consistent; nest for containment, stop at two levels; lowercase, hyphens, no file extensions, no trailing slashes, no verbs anywhere. (Part 4)"
 },
 {
  "t": "TIER 1 - EXPECTED OF EVERYONE",
  "q": "8 ▶ Path vs query vs header vs body — where does data belong?",
  "a": "Path: WHICH resource. Query: HOW a collection is returned (filter/sort/page). Headers: metadata about the request (auth, formats, caching). Body: data being created or updated. Neither secrets in URLs (they hit a dozen logs) nor bodies on GET. (Part 3)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "9 ▶ What is wrong with offset pagination, and what replaces it?",
  "a": "Offset gets progressively slower (every skipped row is generated and discarded) and skips/duplicates when data changes between requests — “row 41” is not stable. Cursor (keyset) pagination: an opaque “where I left off” (sort key + ID tiebreaker) — fast at any depth, stable under inserts, no page jumping. (Part 6)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "10 ▶ Which “harmless” change quietly BREAKS clients — and the mutual discipline?",
  "a": "Tightening validation (sloppy-but-accepted data suddenly fails) and adding enum values (clients hard-code switches). Discipline: servers ADD rather than change; clients TOLERATE rather than assume — ignore unknown fields. That is evolvability in practice. (Part 2)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "11 ▶ Cancel an order — the three legitimate approaches (A, B, C)?",
  "a": "A: PATCH /orders/42 {\"status\":\"cancelled\"} — when it is really a field. B: POST /orders/42/cancellation — event as sub-resource, carries who/why/when, idempotency-friendly. C: POST /orders/42/cancel — explicit action; what Stripe and GitHub do. Defend the choice; clarity beats purity. (Part 4)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "12 ▶ Design a good error response — what must it carry?",
  "a": "Right status code (machines branch here); machine-readable codes (“required”, “insufficient_funds”) — never prose clients must parse; all validation failures at once; a request/correlation ID; no internals. RFC 9457 shape: type, title, status, detail, instance, request_id. (Part 5)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "13 ▶ JWTs, honestly — signed or encrypted, and the biggest weakness?",
  "a": "SIGNED, not encrypted — anyone can read the payload; never put secrets in. Signature proves integrity without a DB lookup — but statelessness means you CANNOT easily revoke: valid until expiry. Mitigation: short-lived access tokens + revocable refresh tokens; validate sig, exp, iss, aud; PIN the algorithm (alg:none / HS256 downgrade forgeries). (Part 7)"
 },
 {
  "t": "TIER 2 - DIFFERENTIATORS",
  "q": "14 ▶ CORS — who enforces it, what it protects, and what the OPTIONS is?",
  "a": "Browsers ONLY — curl, Postman, servers ignore it; it protects USERS from cross-origin reads, not your API from attackers. Non-simple requests trigger an OPTIONS preflight the server must answer with Access-Control-Allow-* headers. Allow-Origin:* cannot combine with credentials — echo specific, allowlisted origins. (Part 7)"
 },
 {
  "t": "TIER 3 - SENIOR SIGNAL",
  "q": "15 ▶ A POST timed out. How do you make it safe to retry, and how do you stop silent lost updates?",
  "a": "Idempotency-Key: client-generated per logical operation, kept across retries; server stores the first result and returns it for repeats (24h+ retention, concurrent duplicates → 409). Lost updates: ETag from GET + If-Match on PATCH → 412 on conflict — explicit, handleable conflict instead of silent overwrites. (Part 11)"
 },
 {
  "t": "TIER 3 - SENIOR SIGNAL",
  "q": "16 ▶ Narrate the full journey of one API call.",
  "a": "DNS (cached per TTL; stale cache is a real failure mode) → TCP three-way handshake (one round trip) → TLS handshake (1–2 more; why HTTPS has fixed startup cost and reuse matters) → request serialized exactly as Part 3’s text → intermediaries (CDN may end it there; load balancer; gateway — the layered system in action) → application: route, auth, authorize, validate, query → compressed, cached response → connection kept alive. (Part 10)"
 },
 {
  "t": "TIER 3 - SENIOR SIGNAL",
  "q": "17 ▶ The HTTP version through-line: what did 1.1, 2, and 3 each fix?",
  "a": "1.1: persistent connections (keep-alive) + Host header + caching headers — but head-of-line blocking, hence ~6 parallel connections. H2: multiplexing + HPACK over TCP — fixed app-level HOL; TCP-level HOL remained. H3: QUIC over UDP — independent streams, faster handshake, connection migration. Consequence: bundling and domain sharding are counterproductive on H2/H3. (Part 10)"
 },
 {
  "t": "TIER 3 - SENIOR SIGNAL",
  "q": "18 ▶ When do you choose GraphQL or gRPC over REST — and what do you give up?",
  "a": "GraphQL: clients need widely varying subsets of a graph; mobile over-fetching/N+1 pain — you give up HTTP caching (one POST to /graphql), add query-depth limiting, and rate limiting gets harder. gRPC: internal service-to-service where you control both ends — you give up browser callability, hand-debuggability, and accept generated-stub coupling (fine inside a boundary). Industry pattern: REST at the edge, gRPC/events internally. (Part 12)"
 }
],
